<?php
require "config.php"; require "auth.php"; requireAdmin();
$results=$pdo->query("SELECT r.result_id,u.username,u.email,q.title,q.category,r.score,r.total_questions,r.percentage,r.taken_at FROM results r JOIN users u ON u.user_id=r.user_id JOIN quizzes q ON q.quiz_id=r.quiz_id ORDER BY r.result_id DESC")->fetchAll();
